    $catalog['crm']['lessons']['crm-orientation']['sections'][]=['Η καρτέλα «Οι υπενθυμίσεις μου»',[
        'Στο Melas CRM θα βρεις στο πλαϊνό μενού τις προσωπικές υπενθυμίσεις. Συγκεντρώνονται τα επόμενα βήματα των δικών σου leads και, εφόσον ο ρόλος σου έχει πρόσβαση στις εταιρικές επικοινωνίες, εκείνων που σου έχουν ανατεθεί. Η ένδειξη «εκπρόθεσμη» αφορά την προγραμματισμένη ώρα, όχι αυτόματη αξιολόγηση της απόδοσής σου. Η αναβολή μετακινεί την προσωπική υπενθύμιση και η ολοκλήρωση κλείνει μόνο αυτήν, όχι την εμπορική υπόθεση.',
        'Οι υπενθυμίσεις είναι εσωτερικές. Η σελίδα ενημερώνεται όταν την ανοίγεις· δεν στέλνει μηνύματα σε πελάτες ή ειδοποιήσεις με κλειστό browser. Στην καρτέλα του δικού σου lead επίλεξε «Έλεγχος επικοινωνίας & επόμενο βήμα», όρισε ώρα και συγκεκριμένη ενέργεια. Αλλαγή στο επόμενο βήμα δημιουργεί νέα εκκρεμότητα ακόμη κι αν είχες ολοκληρώσει την προηγούμενη.'
    ]];
    $catalog['crm']['lessons']['crm-orientation']['sections'][]=['Έλεγχος επικοινωνίας και τεκμηριωμένες ενδείξεις',[
        'Αν η επαφή ζητήσει διακοπή προωθητικής επικοινωνίας, καταχώρισε DNC μέσα στον έλεγχο επαφής με ημερομηνία και αιτιολογία. Το Melas CRM αναγνωρίζει τα ίδια καταχωρισμένα τηλέφωνα ή email σε άλλες καρτέλες και προειδοποιεί τους υπαλλήλους. Η αποστολή εταιρικής πρότασης από το CRM ελέγχει επίσης τον αποκλεισμό. Δεν εμποδίζει φυσικά μια κλήση έξω από το σύστημα και δεν υποκαθιστά τα εξωτερικά μητρώα ή τις νόμιμες υποχρεώσεις.',
        'Μόνο ο ιδιοκτήτης και ο εξουσιοδοτημένος διαχειριστής καταχωρίζουν έλεγχο τηλεφωνικής επικοινωνίας και τεκμηριωμένη άρση αποκλεισμού. Η άρση δεν επαναφέρει παλιά έγκριση. Ο έλεγχος λήγει στην καταχωρισμένη ώρα και παύει να ισχύει αν αλλάξουν τα στοιχεία επαφής. Δεν αποτελεί άδεια αποστολής email. Τα προστατευμένα στοιχεία παραμένουν κρυφά από τον εγκρίνοντα μέχρι την προβλεπόμενη κατοχύρωση.',
        'Οι δείκτες fit και intent οργανώνουν τις παρατηρήσεις σου. Κάθε άξονας έχει τέσσερα σαφή κριτήρια, με 25 μονάδες ανά τεκμηριωμένο «ναι». Το «άγνωστο» εμφανίζεται χωριστά ώστε να μη βαφτίζεται βεβαιότητα. Το σύστημα υπολογίζει τον δείκτη, αλλά δεν επιβεβαιώνει μόνο του τα γεγονότα: χρειάζεται σημείωση τεκμηρίων. Ούτε 100/100 εγκρίνει lead, μεταφέρει ιδιοκτησία ή δημιουργεί προμήθεια. Αυτές είναι χωριστές, ελεγχόμενες ενέργειες. Οι λειτουργίες αυτές προστέθηκαν στο Melas CRM, όχι στο Distillogic CRM.'
    ]];
    foreach($catalog as &$group) {
        // Theory precedes graded practice, including newly added material.
        $theory=[];$labs=[];
        foreach($group['lessons'] as $id=>$lesson) {
            if(($lesson['type']??'')==='lab'){$labs[$id]=$lesson;continue;}
            if(isset($bank[$id])) {
                $lesson['legacy_quiz']=$lesson['quiz'];
                $lesson['quiz']=[];
                foreach($bank[$id] as $i=>$row)$lesson['quiz'][]=academy_challenge_question($row,$id.':'.$i);
                $lesson['assessment_revision']='challenge-33';
            }
            $theory[$id]=$lesson;
        }
        $group['lessons']=$theory+$labs;
    }unset($group);
    return $catalog;
}

function academy_lessons(): array
{
    $lessons = [];
    foreach (academy_catalog() as $pillarId => $pillar) {
        foreach ($pillar['lessons'] as $id => $lesson) {
            $lessons[$id] = $lesson + ['id' => $id, 'pillar' => $pillarId, 'pillar_title' => $pillar['title']];
        }
    }
    return $lessons;
}
